/// Latar padang. [weather] mengatur matahari dan awan mendung.
String sceneSvg(String weather, {bool big = true}) {
  final sunOpacity = weather == 'cerah' ? 1.0 : weather == 'berawan' ? .35 : 0.0;
  final storm = weather == 'cerah' ? 0 : 1;
  final posts = [for (var i = 0; i < 16; i++) if (i < 11 || i == 15) '<path d="M${i * 25 + 4} 140 v-26 l4 -4 l4 4 v26z"/>'].join();
  return '''<svg viewBox="0 0 400 230" xmlns="http://www.w3.org/2000/svg">
<defs><linearGradient id="hdSky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#4fbdf0"/><stop offset="1" stop-color="#c9efff"/></linearGradient></defs>
<rect width="400" height="230" fill="url(#hdSky)"/>
<g opacity="$sunOpacity"><circle cx="340" cy="36" r="30" fill="#fff3a6" fill-opacity=".6"/><circle cx="340" cy="36" r="19" fill="#ffd23f" stroke="#f0a91c" stroke-width="3"/></g>
<g fill="#ffffff"><ellipse cx="70" cy="32" rx="28" ry="10"/><ellipse cx="90" cy="25" rx="17" ry="12"/><ellipse cx="54" cy="27" rx="12" ry="9"/><ellipse cx="215" cy="46" rx="24" ry="8"/><ellipse cx="230" cy="40" rx="13" ry="9"/></g>
<g opacity="$storm" fill="#b4c3cf" stroke="#8a9cab" stroke-width="2"><ellipse cx="150" cy="26" rx="40" ry="13"/><ellipse cx="180" cy="18" rx="24" ry="13"/><ellipse cx="300" cy="30" rx="44" ry="13"/><ellipse cx="330" cy="22" rx="26" ry="13"/></g>
<path d="M0 104 q60 -42 130 -10 q70 -36 150 -6 q60 -24 120 6 V230 H0z" fill="#a6e463" stroke="#5c9a2a" stroke-width="3"/>
<path d="M0 118 q100 -30 200 -2 q100 22 200 -6 V230 H0z" fill="#8bd84a" stroke="#4f9a22" stroke-width="3"/>
<g transform="translate(26 66)"><rect x="8" y="24" width="7" height="24" rx="2" fill="#8a5222" stroke="#4a2708" stroke-width="2"/><circle cx="11" cy="20" r="17" fill="#4fb33a" stroke="#2c6e1c" stroke-width="2.5"/><circle cx="2" cy="27" r="10" fill="#5cc244" stroke="#2c6e1c" stroke-width="2.5"/><circle cx="21" cy="27" r="10" fill="#45a332" stroke="#2c6e1c" stroke-width="2.5"/><circle cx="6" cy="14" r="3" fill="#e2463a"/><circle cx="17" cy="21" r="3" fill="#e2463a"/><circle cx="1" cy="27" r="2.6" fill="#e2463a"/></g>
${big ? _barn : _coop}
<rect x="0" y="132" width="400" height="98" fill="#7fd03e"/>
<g fill="none" stroke="#4f9a22" stroke-width="2.5" stroke-linecap="round"><path d="M40 190 l3 -8 l3 8 M120 212 l3 -8 l3 8 M232 198 l3 -8 l3 8 M352 208 l3 -8 l3 8 M300 182 l3 -8 l3 8 M180 176 l3 -8 l3 8"/></g>
<circle cx="60" cy="214" r="4.5" fill="#ffffff" stroke="#c9c2b0" stroke-width="1"/><circle cx="60" cy="214" r="1.8" fill="#ffd23f"/><circle cx="268" cy="220" r="4.5" fill="#ff8fb1" stroke="#d4527a" stroke-width="1"/><circle cx="268" cy="220" r="1.8" fill="#ffd23f"/><circle cx="378" cy="186" r="4.5" fill="#ffffff" stroke="#c9c2b0" stroke-width="1"/><circle cx="378" cy="186" r="1.8" fill="#ffd23f"/>
<path d="M0 121 H400 M0 133 H400" stroke="#6b3b12" stroke-width="6"/><path d="M0 120 H400 M0 132 H400" stroke="#c98a4b" stroke-width="3"/>
<g fill="#d9995a" stroke="#6b3b12" stroke-width="2">$posts</g>
${big ? _bales : _pond}
</svg>''';
}

