const _bales = '<g transform="translate(200 150)" stroke="#a8650a" stroke-width="2"><ellipse cx="0" cy="14" rx="16" ry="12" fill="#f5c04a"/><path d="M-12 8 h24 M-14 14 h28 M-12 20 h24" stroke-width="1.3"/><ellipse cx="26" cy="20" rx="12" ry="9" fill="#f5c04a"/></g>';
const _pond = '<g transform="translate(96 178)"><ellipse cx="0" cy="0" rx="58" ry="20" fill="#5cc0f5" stroke="#1b5f96" stroke-width="3"/><ellipse cx="-14" cy="-5" rx="18" ry="5" fill="#a8e2ff"/><ellipse cx="26" cy="6" rx="8" ry="4" fill="#4fb33a" stroke="#2c6e1c" stroke-width="1.5"/><circle cx="28" cy="4" r="2" fill="#ff8fb1"/></g>';
